import{_ as t,o as a,c as o,ah as n}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Getting started","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/prise-en-main.md","filePath":"src/en/guide/prise-en-main.md"}'),i={name:"en/guide/prise-en-main.md"};function s(r,e,h,l,c,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>This page applies to every role: signing in, your profile, security, notifications and language work the same way whether you&#39;re an administrator, a teacher, a parent or a student. The role-specific guides (left-hand menu) don&#39;t repeat this information.</p><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in&quot;">​</a></h2><p>Open your school&#39;s address in a browser and enter your email and password on the sign-in screen. If your school has enabled it, you can also sign in with a Google or Apple account.</p><p>If two-factor authentication is enabled on your account, you&#39;ll be asked for an extra code after your password (see &quot;Two-factor authentication&quot; below).</p><p>Once signed in, you land on your dashboard — its content depends on your role.</p><h2 id="account-settings" tabindex="-1">Account settings <a class="header-anchor" href="#account-settings" aria-label="Permalink to &quot;Account settings&quot;">​</a></h2><p>The <strong>Settings</strong> menu (from your avatar, at the top of the screen) groups everything related to your personal account, regardless of your role:</p><ul><li><strong>Profile</strong> — change your name, email address and profile picture. If you change your email, a &quot;Your email address is not verified&quot; message appears until you click the link sent to that address.</li><li><strong>Security</strong> — change your password, enable two-factor authentication, manage your passkeys (passwordless sign-in) and review your active sessions.</li><li><strong>Appearance</strong> — choose between light, dark or automatic theme.</li><li><strong>Language</strong> — choose the app&#39;s language (French or English). This choice immediately changes every label, including this guide&#39;s, if you open it from within the app.</li><li><strong>Notifications</strong> — enable push notifications on this device.</li></ul><h3 id="two-factor-authentication-2fa" tabindex="-1">Two-factor authentication (2FA) <a class="header-anchor" href="#two-factor-authentication-2fa" aria-label="Permalink to &quot;Two-factor authentication (2FA)&quot;">​</a></h3><p>Under <strong>Settings → Security → Two-factor authentication</strong>, click <strong>Enable 2FA</strong>. You&#39;ll then be asked for a secret code at every sign-in; it comes from an authenticator app (TOTP) on your phone, after scanning the code shown on screen. To turn it off, go back to that same page and click <strong>Disable 2FA</strong>.</p><h3 id="active-sessions" tabindex="-1">Active sessions <a class="header-anchor" href="#active-sessions" aria-label="Permalink to &quot;Active sessions&quot;">​</a></h3><p><strong>Settings → Security → Active sessions</strong> lists every device currently signed in to your account, with the device, IP address and last activity. The device you&#39;re using right now is marked <strong>Current device</strong>. You can:</p><ul><li><strong>Sign out</strong> a specific device (it will need to sign in again),</li><li><strong>Sign out other devices</strong> to close every session except the current one — useful if you think a device should no longer have access to your account.</li></ul><h3 id="push-notifications" tabindex="-1">Push notifications <a class="header-anchor" href="#push-notifications" aria-label="Permalink to &quot;Push notifications&quot;">​</a></h3><p><strong>Settings → Notifications</strong> lets you enable push notifications on the device you&#39;re using. Once enabled, you&#39;re notified as soon as something needs your attention (for example a site-transfer request awaiting your approval). The <strong>Enable</strong>/<strong>Disable</strong> button toggles this; if it says push notifications aren&#39;t supported, your browser or device doesn&#39;t allow them.</p><h2 id="the-notification-bell" tabindex="-1">The notification bell <a class="header-anchor" href="#the-notification-bell" aria-label="Permalink to &quot;The notification bell&quot;">​</a></h2><p>At the top of the screen, the bell shows a badge when you have unread notifications (for example an application to process, or a request to approve). Click a notification to open it and mark it as read, or use <strong>Mark all as read</strong> to clear the list at once.</p><h2 id="approving-a-request-straight-from-a-notification" tabindex="-1">Approving a request straight from a notification <a class="header-anchor" href="#approving-a-request-straight-from-a-notification" aria-label="Permalink to &quot;Approving a request straight from a notification&quot;">​</a></h2><p>Some notifications don&#39;t just inform you: they open a <strong>quick review</strong> screen, deliberately stripped down, where you decide without navigating into the rest of the app. It&#39;s built to be used from a phone.</p><p>Three requests work this way:</p><table tabindex="0"><thead><tr><th>Request</th><th>Who decides</th></tr></thead><tbody><tr><td>Moving a student to another site</td><td>Administration or front desk</td></tr><tr><td>Moving a staff member</td><td>Administration</td></tr><tr><td>An expense awaiting approval</td><td>Administration</td></tr></tbody></table><p>The screen shows the request&#39;s details and two actions: <strong>Approve</strong>, which decides immediately, or <strong>Reject</strong>, which first asks for a reason — a reason then visible to whoever filed the request.</p><p>You can still handle these the usual way, from the matching queue in the menu. Quick review is a shortcut, not a separate track: a request already handled from a notification shows as handled in the queue, and the other way round.</p><h2 id="why-some-menus-don-t-appear" tabindex="-1">Why some menus don&#39;t appear <a class="header-anchor" href="#why-some-menus-don-t-appear" aria-label="Permalink to &quot;Why some menus don&#39;t appear&quot;">​</a></h2><p>ERA is sold by module: a school only activates the ones it needs. If an expected menu isn&#39;t there, it isn&#39;t necessarily a permissions problem — the module may simply not be part of the school&#39;s licence.</p><p>Two possible causes, worth telling apart before reporting a fault:</p><ul><li><strong>Your role</strong> doesn&#39;t grant that function. A teacher doesn&#39;t see the cash desk; a cashier doesn&#39;t enter grades.</li><li><strong>The module isn&#39;t licensed</strong> for the school. In that case nobody sees the function, whatever their role, and opening the address directly shows a message saying the function isn&#39;t included.</li></ul><p>Your administrator can confirm which of the two applies.</p><h2 id="switching-language" tabindex="-1">Switching language <a class="header-anchor" href="#switching-language" aria-label="Permalink to &quot;Switching language&quot;">​</a></h2><p>The language switcher (<strong>Settings → Language</strong>, or the language icon in the header depending on your role) switches the whole interface between French and English immediately — no need to sign in again.</p><h2 id="terms-of-use-and-personal-data" tabindex="-1">Terms of use and personal data <a class="header-anchor" href="#terms-of-use-and-personal-data" aria-label="Permalink to &quot;Terms of use and personal data&quot;">​</a></h2><p>Two pages are open to everyone, including signed-out visitors, from the links at the bottom of the home page:</p><ul><li><strong>Terms of use and sale</strong> — what your school&#39;s licence covers, maintenance, and the hosting plans.</li><li><strong>Privacy policy</strong> — which data ERA processes about students, families and staff, how long it is kept, and who can access it.</li></ul><p>Both pages follow the application&#39;s language: they display in French or English according to your <strong>Settings → Language</strong> choice.</p>',35)])])}const p=t(i,[["render",s]]);export{g as __pageData,p as default};
